type ListRequirementPopoCommandsParams struct {
	WorkspaceID   pgtype.UUID `json:"workspace_id"`
	RequirementID pgtype.UUID `json:"requirement_id"`
	PageOffset    int32       `json:"page_offset"`
	PageLimit     int32       `json:"page_limit"`
}

func (q *Queries) ListRequirementPopoCommands(ctx context.Context, arg ListRequirementPopoCommandsParams) ([]PopoBridgeCommand, error) {
	rows, err := q.db.Query(ctx, listRequirementPopoCommands,
		arg.WorkspaceID,
		arg.RequirementID,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PopoBridgeCommand{}
	for rows.Next() {
		var i PopoBridgeCommand
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.BridgeID,
			&i.InstallationID,
			&i.Type,
			&i.DeliveryID,
			&i.Payload,
			&i.Status,
			&i.LeaseExpiresAt,
			&i.RemoteMessageID,
			&i.LastError,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Attempt,
			&i.RequirementID,
			&i.RequirementKind,
			&i.OccurrenceID,
			&i.OperationID,
			&i.RecipientUserID,
			&i.RecipientBindingID,
			&i.RequirementRevision,
			&i.IssueRevision,
			&i.SnapshotPayload,
			&i.RequestHash,
			&i.PayloadHash,
			&i.LeaseID,
			&i.DispatchedAt,
			&i.NotSent,
			&i.Retryable,
			&i.PartialDelivery,
			&i.EvidenceFinalized,
			&i.NeedsReconcile,
			&i.NextAttemptAt,
			&i.ExpiresAt,
			&i.AcceptedAt,
			&i.DeliveredAt,
			&i.SupersededAt,
			&i.UnknownAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

