const supersedePendingRequirementPopoCommands = `-- name: SupersedePendingRequirementPopoCommands :execrows
UPDATE popo_bridge_command AS cmd
SET status = CASE WHEN cmd.status = 'unknown' THEN cmd.status ELSE 'superseded' END,
    superseded_at = CASE
        WHEN cmd.status = 'unknown' THEN cmd.superseded_at
        ELSE COALESCE(cmd.superseded_at, now())
    END,
    lease_id = NULL,
    lease_expires_at = NULL,
    updated_at = now()
WHERE cmd.workspace_id = $1
  AND cmd.requirement_id = $2
  AND cmd.status IN ('pending', 'leased', 'failed', 'conflict')
  AND (cmd.status <> 'leased' OR cmd.dispatched_at IS NULL)
  AND ($3::text IS NULL OR cmd.requirement_kind = $3::text)
  AND ($4::uuid IS NULL
       OR cmd.occurrence_id = $4::uuid)
`

type SupersedePendingRequirementPopoCommandsParams struct {
	WorkspaceID   pgtype.UUID `json:"workspace_id"`
	RequirementID pgtype.UUID `json:"requirement_id"`
	Kind          pgtype.Text `json:"kind"`
	OccurrenceID  pgtype.UUID `json:"occurrence_id"`
}

// A delivery that reached a POPO bridge (leased and dispatched) may still be in
// flight, so it keeps its lease and waits for a receipt. Unknown outcomes are
// never rewritten by business supersession.
func (q *Queries) SupersedePendingRequirementPopoCommands(ctx context.Context, arg SupersedePendingRequirementPopoCommandsParams) (int64, error) {
	result, err := q.db.Exec(ctx, supersedePendingRequirementPopoCommands,
		arg.WorkspaceID,
		arg.RequirementID,
		arg.Kind,
		arg.OccurrenceID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

